"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "„Mur trzyma potwory na zewnątrz. Dopóki jesteś w środku, jesteś bezpieczny.”",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "„Dziki zjadają mi rzepę. Jak jakieś zobaczysz, poluj na nie!”",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "„Widziałeś kiedyś smoka? Lian mówi, że na Ognistej Górze jakieś są.”",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "„Kiedyś Kazehana było spokojnym miastem. Potem przyszły kamienie.”",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "„Każdy kamień ma własną duszę. I każdy zostawia coś innego.”",
