"Stadt · sicherer Ort": "Miasto · bezpieczne miejsce",
"Lager · sicherer Ort": "Obóz · bezpieczne miejsce",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "Wielkie miasto Kazehana z zielonymi Słonecznymi Łąkami.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Gęsty las iglasty z bandytami, pająkami i niedźwiedziami. Pajęcza Jaskinia i Piwnica Bandytów.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Zakurzona dolina orków i skorpionów. Twierdza Orków.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Szara równina popiołu z ogrami i demonami. Krypta Umarłych.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Lodowe szczyty z lodowymi wilkami, yeti i duchami mrozu. Lodowa Grota.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Mgliste bagno pełne nieumarłych, wiedźm i ghuli.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Czarny bazalt i rzeki lawy, golemy, ogniste demony i smoki. Smocze Leże.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Wirujesz wokół siebie, trafiasz wszystkich wrogów wokół i na chwilę ich ogłuszasz.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Wzmocnienie: wokół ciebie skaczą błyskawice. Większa szybkość ataku i ruchu.",
"Erdbeben": "Trzęsienie Ziemi",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Tupiesz, a ziemia drży: wszyscy wrogowie wokół są ogłuszeni na {0} s.",
"Starker Körper": "Silne Ciało",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Wzmocnienie: twoje ciało twardnieje jak kamień. Więcej obrony i mniej otrzymywanych obrażeń.",
"Geistesschlag": "Cios Ducha",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Skupiony cios z pełną siłą w jeden cel. Bardzo wysokie obrażenia.",
"Kriegsschrei": "Okrzyk Bojowy",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Okrzyk paraliżujący wrogów: są wolniejsi i otrzymują więcej obrażeń.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Obracasz się z dwoma sztyletami i trafiasz wszystkich wrogów wokół.",
"Schattensprung": "Skok Cienia",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Skaczesz przez cienie naprzód i tniesz wszystko na drodze.",
"Lähmende Klinge": "Paraliżujące Ostrze",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Cios w ścięgna: cel jest ogłuszony na {0} s i zatruty na {1} s.",
"Schattenmantel": "Płaszcz Cienia",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Wzmocnienie: cienie cię otulają. Więcej uniku i więcej trafień krytycznych.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Wzmocnienie: smocza moc w ciebie wpływa. Więcej ataku i obrażeń umiejętności.",
"Geisterfaust": "Pięść Ducha",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Pięść z mocy ducha trafia cel i ogłusza go na {0} s.",
"Windfessel": "Więzy Wiatru",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Wirujący wiatr pęta wrogów wokół: są wolniejsi i podatni na ciosy.",
"Segen": "Błogosławieństwo",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Wzmocnienie: mniej otrzymywanych obrażeń, regeneracja życia, więcej trafień krytycznych.",
"Heilung": "Uzdrowienie",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Leczy część twojego życia, a potem daje ci więcej ataku.",
