"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Ledwie psy odeszły, lisy krążą wokół obór. Przegoń je z powrotem na łąki",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Dziki zjadają chłopom plony. Zima bez zapasów byłaby naszym końcem",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Na skraju łąk żarzy się kamień gniewu. Jego gniew doprowadza zwierzęta do szału – rozbij go",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Dobrze, że Bao cię przysyła. Bandyci napadają każdego kupca na leśnej drodze. Przegoń ich",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Tutejsze dziki mają ciernie zamiast szczeciny. Rozrywają nasze pułapki – i traperów",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "W głębi lasu olbrzymie pająki rozpinają sieci nad drogami. Wypal je, jeśli trzeba",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Pośrodku lasu rośnie kamień cierni. Jego pnącza duszą każde drzewo. Zniszcz go",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Hagen cię przysyła? To chodź, orkowie stoją już pod palisadą. Osłab ich armię",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Orkowie trzymają hieny jak psy i szczują je na naszych zwiadowców. Rozpraw się ze sforą",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Idris cię przysyła? Bogowie sprzyjają Sahrze. Kobry czyhają przy każdym wodopoju",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Słyszysz ten grzechot? Grzechotniki. Setki. Karawany nie odważą się już wyruszyć",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Na Mroźnym Szczycie widziano yeti wielkie jak domy. Przynieś ich skóry jako dowód",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Mamuty szaleją, odkąd mróz nie ustępuje. Tratują nasze szopy z zapasami",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Tam, gdzie stoi kamień ciszy, milknie każda pieśń. Przywróć dźwięk na szczyt",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "Ostatni i najpotężniejszy ze wszystkich kamieni dusz. Zniszcz go, a kamienie przestaną rosnąć",
"Hunde aus der Asche": "Psy z popiołu",
"Diebe im Zwielicht": "Złodzieje o zmierzchu",
"Wölfe aus dem Nebel": "Wilki z mgły",
"Die bleichen Geweihe": "Blade poroża",
"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "Nocne jelenie o świecących porożach biegną na nasze płoty, jakby coś je goniło. Zatrzymaj je",
"Die Leitwölfe": "Przewodnicy stad",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "Każde mgliste stado podąża za nocnym przewodnikiem. Bez niego stado rozprasza się we mgle",
"Keiler im Mondkraut": "Dziki w księżycowym zielu",
"Glut im Aschewald": "Żar w popielnym lesie",
"Räuber in der Asche": "Rabusie w popiele",
"Glühende Hauer": "Rozżarzone kły",
"Die Keiler hier tragen Glut im Borstenkamm. Wo sie sich reiben, fängt das Unterholz Feuer": "Tutejsze dziki noszą żar w grzebieniu. Gdzie się ocierają, zapala się poszycie",
"Schützen im Rauch": "Strzelcy w dymie",
"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "Strzelcy sadzy strzelają z dymu, zanim ktoś ich zobaczy. Wykurz ich ze spalonych koron",
"Graue Netze": "Szare sieci",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "Dwa kamienie chciwości wabią rabusiów jak żar ćmy. Rozbij je",
"Rußgraue Jäger": "Szarzy jak sadza łowcy",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "Rysie sadzy są niewidoczne w popiele. Nasi węglarze nie wracają. Bądź czujniejszy od nich",
"Kohlenbären": "Węglowe niedźwiedzie",
"Knochen im Sand": "Kości w piasku",
"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "Ascan cię przysyła? To chodź, łamignaty stoją już pod naszym pierścieniem. Rozbij ich szeregi",
"Aashyänen": "Padlinożerne hieny",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "Hieny idą za łamignatami i zjadają, co ci zostawią. Rozpraw się ze sforą",
"Die Knochenruferinnen": "Przywoływaczki kości",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "Przywoływaczki wyśpiewują kości z piasku. Bez ich pieśni umarli leżą dalej",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "Z wydm sterczą dwa czarne kamienie, a wokół zbierają się kości. Odbierz im środek",
"Bleiche Stachel": "Blade żądła",
"Die Knochenhauptmänner": "Kościani kapitanowie",
"Die Beinbrecher gehorchen Hauptmännern in alten Rüstungen. Fällst du sie, zerfällt das Heer": "Łamignaty słuchają kapitanów w starych zbrojach. Powal ich, a armia się rozpadnie",
"Ein Stein der Asche verbrennt die Wüste von innen. Lösch ihn aus, bevor nur Staub bleibt": "Kamień popiołu wypala pustynię od środka. Zgaś go, zanim zostanie tylko pył",
"Rot am Horizont": "Czerwień na horyzoncie",
"Ossian hat recht, dich zu schicken. Blutoger stampfen jede Nacht gegen unsere Inseln. Halte sie fern": "Ossian słusznie cię przysyła. Krwawe ogry co noc tratują nasze wyspy. Trzymaj je z dala",
"Wargrudel der Steppe": "Stado wargów ze stepu",
"Steppenwargs jagen in großen Rudeln durch das rote Gras. Jag das Rudel, bevor es uns jagt": "Stepowe wargi polują dużymi stadami w czerwonej trawie. Upoluj stado, zanim ono upoluje nas",
"Blutdämonen": "Krwawe demony",
"Aus den roten Tümpeln steigen Blutdämonen. Treib sie zurück in die Tiefe": "Z czerwonych sadzawek wychodzą krwawe demony. Zepchnij je z powrotem w głąb",
"Die Steine der Glut heizen die Tümpel auf, bis sie kochen. Lösche sie aus": "Kamienie żaru grzeją sadzawki, aż zawrą. Zgaś je",
"Blutmäuler": "Krwawe Paszcze",
"Blutmäuler bewachen die Tümpel der Dämonen. Wer sie besiegt, kann den Quellen nahe kommen": "Krwawe Paszcze strzegą sadzawek demonów. Kto je pokona, zbliży się do źródeł",
"Die Klippenfeste": "Twierdza na urwiskach",
