"Zwei blitzschnelle Hiebe über Kreuz treffen die Gegner direkt vor dir": "Dwa błyskawiczne cięcia na krzyż trafiają wrogów tuż przed tobą",
"Einführung starten": "Rozpocznij wprowadzenie",
"Kurzer Rundgang: wo was ist, was der Schmied macht und mehr": "Krótki przegląd: co gdzie jest, co robi kowal i więcej",
