"kauft deine Sachen": "kupuje twoje rzeczy",
"Willkommen in Seelenstein": "Witaj w Seelenstein",
"Diese kurze Einführung zeigt dir, wo was ist. Das Spiel läuft nebenher weiter": "To krótkie wprowadzenie pokaże ci, co gdzie jest. Gra toczy się dalej w tle",
"Du kannst sie jederzeit überspringen und später in der Hilfe wiederholen": "Możesz je pominąć w każdej chwili i powtórzyć później w pomocy",
"Laufen und angreifen": "Ruch i atak",
"Laufen mit W, A, S, D oder den Pfeiltasten. Ein Klick auf den Boden läuft dorthin": "Poruszaj się W, A, S, D lub strzałkami. Kliknięcie w ziemię prowadzi tam",
"Berühre die linke Bildschirmhälfte und ziehe, um zu laufen": "Dotknij lewej połowy ekranu i przeciągnij, by iść",
"Unten in der Leiste liegen deine fünf Fertigkeiten. Ab Stufe {0} kommt die Ultimative Attacke dazu": "Pięć umiejętności leży na pasku na dole. Od poziomu {0} dochodzi atak ostateczny",
"Oben links siehst du dein Leben (rot) und dein Mana (blau). Fertigkeiten kosten Mana": "W lewym górnym rogu widać życie (czerwone) i manę (niebieską). Umiejętności kosztują manę",
"Tippst du ein Teil an, siehst du jeden Wert im Vergleich: grün mehr, rot weniger": "Dotknij przedmiotu, by porównać każdą wartość: zielone więcej, czerwone mniej",
"Der Schmied": "Kowal",
"Im Kanal schreibst du hier mit den anderen Spielern. Oben im Chat wählst du Global, Gilde oder Ort": "Na kanale piszesz tu z innymi graczami. U góry czatu wybierasz Globalny, Gildia lub Lokalny",
