"Die Hilfe erklärt alles genauer – dort startest du diese Einführung jederzeit neu": "Pomoc wyjaśnia wszystko dokładniej – tam w każdej chwili uruchomisz to wprowadzenie",
"Sprich mit den Leuten mit Ausrufezeichen und jage die Monster vor der Stadt. Gute Jagd": "Rozmawiaj z osobami z wykrzyknikiem i poluj na potwory za miastem. Udanych łowów",
